-- Table structure for table `fraud_case`
--

DROP TABLE IF EXISTS `fraud_case`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fraud_case` (
  `Case_ID` bigint NOT NULL AUTO_INCREMENT,
  `User_ID` int NOT NULL,
  `Account_ID` int DEFAULT NULL,
  `Transaction_ID` bigint DEFAULT NULL,
  `Fraud_Type` enum('Account Takeover','Money Laundering','Payment Fraud','UPI Fraud','Mule Account','Identity Fraud') NOT NULL,
  `Label` tinyint(1) NOT NULL,
  `Confidence` decimal(5,4) DEFAULT NULL,
  `Detected_Date` datetime DEFAULT NULL,
  `Status` enum('Open','Under Investigation','Confirmed','False Positive','Closed') DEFAULT 'Open',
  `Source` varchar(100) DEFAULT NULL,
  `Created_At` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`Case_ID`),
  KEY `FK_FRAUD_USER` (`User_ID`),
  KEY `IDX_FRAUD_ACCOUNT` (`Account_ID`),
  KEY `IDX_FRAUD_TRANSACTION` (`Transaction_ID`),
  KEY `IDX_FRAUD_TYPE` (`Fraud_Type`),
  CONSTRAINT `FK_FRAUD_ACCOUNT` FOREIGN KEY (`Account_ID`) REFERENCES `account` (`Account_ID`),
  CONSTRAINT `FK_FRAUD_TRANSACTION` FOREIGN KEY (`Transaction_ID`) REFERENCES `transaction` (`Transaction_ID`),
  CONSTRAINT `FK_FRAUD_USER` FOREIGN KEY (`User_ID`) REFERENCES `customer` (`User_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=2001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

