--
-- Table structure for table `transaction`
--

DROP TABLE IF EXISTS `transaction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `transaction` (
  `Transaction_ID` bigint NOT NULL AUTO_INCREMENT,
  `Sender_Account_ID` int NOT NULL,
  `Receiver_Account_ID` int NOT NULL,
  `Amount` decimal(15,2) NOT NULL,
  `Transaction_Timestamp` datetime NOT NULL,
  `Transaction_Type` enum('Transfer','Payment','Withdrawal','Deposit','Refund') DEFAULT NULL,
  `Channel` enum('UPI','NEFT','RTGS','IMPS','CARD','ATM','NET_BANKING','CASH') DEFAULT NULL,
  `Status` enum('Success','Failed','Pending','Reversed') DEFAULT 'Success',
  `Device_ID` int DEFAULT NULL,
  `IP_Hash` varchar(128) DEFAULT NULL,
  `City` varchar(100) DEFAULT NULL,
  `Merchant_ID` int DEFAULT NULL,
  `UPI_ID` int DEFAULT NULL,
  `Reference_ID` varchar(100) DEFAULT NULL,
  `Is_International` tinyint(1) DEFAULT '0',
  `Is_Reversal` tinyint(1) DEFAULT '0',
  `Parent_Transaction_ID` bigint DEFAULT NULL,
  `Failure_Count` int DEFAULT '0',
  `Created_At` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`Transaction_ID`),
  KEY `FK_TRANSACTION_PARENT` (`Parent_Transaction_ID`),
  KEY `IDX_TRANSACTION_SENDER` (`Sender_Account_ID`),
  KEY `IDX_TRANSACTION_RECEIVER` (`Receiver_Account_ID`),
  KEY `IDX_TRANSACTION_TIME` (`Transaction_Timestamp`),
  KEY `IDX_TRANSACTION_DEVICE` (`Device_ID`),
  KEY `IDX_TRANSACTION_MERCHANT` (`Merchant_ID`),
  KEY `IDX_TRANSACTION_UPI` (`UPI_ID`),
  CONSTRAINT `FK_TRANSACTION_DEVICE` FOREIGN KEY (`Device_ID`) REFERENCES `device` (`Device_ID`),
  CONSTRAINT `FK_TRANSACTION_MERCHANT` FOREIGN KEY (`Merchant_ID`) REFERENCES `merchant` (`Merchant_ID`),
  CONSTRAINT `FK_TRANSACTION_PARENT` FOREIGN KEY (`Parent_Transaction_ID`) REFERENCES `transaction` (`Transaction_ID`),
  CONSTRAINT `FK_TRANSACTION_RECEIVER` FOREIGN KEY (`Receiver_Account_ID`) REFERENCES `account` (`Account_ID`),
  CONSTRAINT `FK_TRANSACTION_SENDER` FOREIGN KEY (`Sender_Account_ID`) REFERENCES `account` (`Account_ID`),
  CONSTRAINT `FK_TRANSACTION_UPI` FOREIGN KEY (`UPI_ID`) REFERENCES `upi_account` (`UPI_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=9001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

