--
-- Table structure for table `upi_account`
--

DROP TABLE IF EXISTS `upi_account`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `upi_account` (
  `UPI_ID` int NOT NULL AUTO_INCREMENT,
  `User_ID` int NOT NULL,
  `Account_ID` int NOT NULL,
  `UPI_Handle_Hash` varchar(128) DEFAULT NULL,
  `PSP_Name` varchar(100) DEFAULT NULL,
  `Registration_Date` date DEFAULT NULL,
  `Status` enum('Active','Inactive','Blocked') DEFAULT 'Active',
  `Last_Used` datetime DEFAULT NULL,
  `Created_At` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`UPI_ID`),
  UNIQUE KEY `UPI_Handle_Hash` (`UPI_Handle_Hash`),
  KEY `IDX_UPI_USER` (`User_ID`),
  KEY `IDX_UPI_ACCOUNT` (`Account_ID`),
  CONSTRAINT `FK_UPI_ACCOUNT` FOREIGN KEY (`Account_ID`) REFERENCES `account` (`Account_ID`),
  CONSTRAINT `FK_UPI_USER` FOREIGN KEY (`User_ID`) REFERENCES `customer` (`User_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=251 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
